export const adaptiveComputeAllocation = (agents, taskQueue) => {
  const priorityScores = agents.map(agent => {
    return agent.getTaskPriority(taskQueue);
  });

  const totalResources = agents.reduce((total, agent) => total + agent.computeResources, 0);

  priorityScores.forEach((score, index) => {
    agents[index].allocateCompute((score / totalResources) * 100);
  });
};